package com.hahhah20.heavenlysworddescent.damage;
import com.hahhah20.heavenlysworddescent.HeavenlySwordDescentPlugin;import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.util.Vector;
public final class DamageManager { public static void damage(HeavenlySwordDescentPlugin p,Player caster,Location c){double cr=p.getConfig().getDouble("skill.radius.core"),mr=p.getConfig().getDouble("skill.radius.middle"),or=p.getConfig().getDouble("skill.radius.outer");double cd=p.getConfig().getDouble("skill.damage.core"),md=p.getConfig().getDouble("skill.damage.middle"),od=p.getConfig().getDouble("skill.damage.outer");boolean self=p.getConfig().getBoolean("skill.damage-caster");for(Entity e:c.getWorld().getNearbyEntities(c,or,4,or)){if(!(e instanceof LivingEntity le)||(!self&&e.equals(caster)))continue;double d=le.getLocation().distance(c),dmg=d<=cr?cd:d<=mr?md:d<=or?od:0;if(dmg<=0)continue;le.damage(dmg,caster);Vector v=le.getLocation().toVector().subtract(c.toVector());if(v.lengthSquared()<.001)v=new Vector(0,0,1);v.normalize().multiply(p.getConfig().getDouble("skill.impact.knockback")*(.5+.5*(1-d/or)));v.setY(p.getConfig().getDouble("skill.impact.vertical-knockback"));le.setVelocity(v);}}}
